begin;
create extension if not exists pgtap with schema extensions;
select extensions.no_plan();
insert into auth.users(id) select ('4d000000-0000-4000-8000-00000000000'||n)::uuid from generate_series(1,6)n;
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) select id,id,'totp','verified',now(),now() from auth.users where id::text like '4d000000-%';
insert into auth.sessions(id,user_id,factor_id,aal) select id,id,id,'aal2' from auth.users where id::text like '4d000000-%';
insert into public.team_profiles(id,full_name,is_active) select id,'Synthetic editorial staff',id::text not like '%5' from auth.users where id::text like '4d000000-%';
insert into public.team_role_assignments select ('4d000000-0000-4000-8000-00000000000'||v.n)::uuid,r.id from(values(1,'platform_owner'),(2,'content_community_lead'),(3,'technical_lead'),(4,'operations_lead'),(5,'platform_owner'))v(n,code)join public.roles r on r.code=v.code;
create function pg_temp.claims(n int,aal text default 'aal2')returns text language sql as $$select json_build_object('sub','4d000000-0000-4000-8000-00000000000'||n,'role','authenticated','aal',aal,'session_id','4d000000-0000-4000-8000-00000000000'||n,'exp',extract(epoch from now()+interval '1 hour')::bigint)::text$$;
create temp table target(n int,id uuid);grant all on target to authenticated;
create function pg_temp.doc(title text default 'Synthetic story')returns jsonb language sql as $$select jsonb_build_object('title',title,'summary','Synthetic summary','author','Synthetic approved byline','categoryId',(public.list_magazine_categories()->0->>'id'),'coverId',null,'body',jsonb_build_array(jsonb_build_object('type','paragraph','text','Safe story text')))$$;
create function pg_temp.a(n int)returns uuid language sql as $$select id from target where target.n=a.n$$;
create function pg_temp.v(n int)returns int language sql as $$select(public.get_staff_magazine(pg_temp.a(n))->>'version')::int$$;
select extensions.is((select count(*) from public.permissions),37::bigint,'no new permission code');
select extensions.is((select count(*) from public.role_permissions),73::bigint,'role mappings unchanged');
select extensions.is(jsonb_array_length(public.list_magazine_categories()),4,'four approved category seeds');
select extensions.ok(not has_table_privilege('anon','business_private.magazine_articles','select'),'canonical articles unavailable to anonymous role');
select extensions.ok(not has_table_privilege('authenticated','business_private.magazine_revisions','SELECT,UPDATE,DELETE'),'direct revision access denied');
select extensions.ok(not has_function_privilege('service_role','public.save_magazine_draft(uuid,integer,text,jsonb)','execute'),'privileged ingress cannot edit editorial data');
select extensions.ok((select bool_and(relrowsecurity) from pg_class where oid in('business_private.magazine_articles'::regclass,'business_private.magazine_categories'::regclass,'business_private.magazine_revisions'::regclass,'business_private.magazine_assets'::regclass)),'all new tables have RLS');
set local role anon;
select extensions.throws_ok($$select public.list_magazine_categories(true)$$,'42501',null,'anon cannot select private category metadata');
select extensions.throws_ok($$select public.list_staff_magazine()$$,'42501',null,'anon cannot list drafts');
set local role authenticated;select set_config('request.jwt.claims',pg_temp.claims(2,'aal1'),true);
select extensions.throws_ok($$select public.list_staff_magazine()$$,'42501',null,'AAL1 editorial access denied');
select set_config('request.jwt.claims',pg_temp.claims(6),true);
select extensions.throws_ok($$select public.list_staff_magazine()$$,'42501',null,'unassigned AAL2 denied');
select set_config('request.jwt.claims',pg_temp.claims(5),true);
select extensions.throws_ok($$select public.list_staff_magazine()$$,'42501',null,'inactive owner denied');
select set_config('request.jwt.claims',pg_temp.claims(3),true);
select extensions.throws_ok($$select public.save_magazine_draft(null,0,'technical-no-authority',pg_temp.doc())$$,'42501',null,'Technology cannot author through technical permission');
select set_config('request.jwt.claims',pg_temp.claims(4),true);
select extensions.throws_ok($$select public.list_staff_magazine()$$,'42501',null,'Operations cannot read editorial drafts');
select set_config('request.jwt.claims',pg_temp.claims(2),true);
insert into target select 1,(public.save_magazine_draft(null,0,'synthetic-magazine-story',pg_temp.doc())->>'id')::uuid;
select extensions.is(public.get_staff_magazine(pg_temp.a(1))->>'published','false','new articles stay draft');
select extensions.is(public.get_published_magazine('synthetic-magazine-story'),null::jsonb,'draft is not publicly retrievable');
select extensions.throws_ok($$select public.save_magazine_draft(null,0,'synthetic-magazine-story',pg_temp.doc())$$,'PT409',null,'duplicate slugs fail safely');
select extensions.throws_ok($$select public.save_magazine_draft(null,0,'../path',pg_temp.doc())$$,'22023',null,'unsafe slug rejected in SQL');
select extensions.throws_ok($$select public.save_magazine_draft(pg_temp.a(1),1,'changed-public-url',pg_temp.doc())$$,'PT409',null,'existing slugs remain stable');
select extensions.throws_ok($$select public.save_magazine_draft(null,0,'html-attack',pg_temp.doc()||'{"body":[{"type":"html","html":"<script>attack</script>"}]}')$$,'22023',null,'raw HTML and embeds rejected');
select extensions.throws_ok($$select public.save_magazine_draft(null,0,'unsafe-link',pg_temp.doc()||'{"body":[{"type":"link","text":"Bad","href":"javascript:alert(1)"}]}')$$,'22023',null,'unsafe link rejected in SQL');
select extensions.throws_ok($$select public.save_magazine_draft(null,0,'missing-body',pg_temp.doc()||'{"body":[]}')$$,'22023',null,'empty body rejected');
select extensions.throws_ok($$select public.save_magazine_draft(null,0,'unregistered-image',pg_temp.doc()||'{"coverId":"4d000000-0000-4000-8000-000000000099"}')$$,'22023',null,'unapproved cover cannot be selected');
select extensions.throws_ok($$select public.feature_magazine(pg_temp.a(1),1,true)$$,'22023',null,'draft cannot be featured');
select extensions.lives_ok($$select public.publish_magazine(pg_temp.a(1),1,true)$$,'Content publishes explicitly');
select extensions.is(public.get_published_magazine('synthetic-magazine-story')->>'title','Synthetic story','public revision available');
select extensions.ok(not public.get_published_magazine('synthetic-magazine-story')?'draft','no private working document in public projection');
select extensions.lives_ok($$select public.save_magazine_draft(pg_temp.a(1),pg_temp.v(1),'synthetic-magazine-story',pg_temp.doc('Private future headline'))$$,'edit working copy while published');
select extensions.is(public.get_published_magazine('synthetic-magazine-story')->>'title','Synthetic story','draft edit never leaks to public revision');
select extensions.throws_ok($$select public.publish_magazine(pg_temp.a(1),1,true)$$,'PT409',null,'stale publish fails');
select extensions.lives_ok($$select public.publish_magazine(pg_temp.a(1),pg_temp.v(1),true)$$,'publication creates a new revision');
select extensions.is(jsonb_array_length(public.get_staff_magazine(pg_temp.a(1))->'revisions'),2,'publication history retained');
select extensions.is(public.get_published_magazine('synthetic-magazine-story')->>'title','Private future headline','explicit republish promotes new copy');
select extensions.lives_ok($$select public.feature_magazine(pg_temp.a(1),pg_temp.v(1),true)$$,'published article can be featured');
insert into target select 2,(public.save_magazine_draft(null,0,'second-synthetic-story',pg_temp.doc('Second story'))->>'id')::uuid;
select public.publish_magazine(pg_temp.a(2),pg_temp.v(2),true);
select extensions.lives_ok($$select public.feature_magazine(pg_temp.a(2),pg_temp.v(2),true)$$,'selecting new featured story replaces previous');
select extensions.is(public.get_staff_magazine(pg_temp.a(1))->>'featured','false','previous feature cleared');
select extensions.is(public.get_staff_magazine(pg_temp.a(2))->>'featured','true','new feature selected');
select extensions.is(public.list_published_magazine()->0->>'slug','second-synthetic-story','featured story sorted first');
select extensions.is(jsonb_array_length(public.list_published_magazine('unknown-category')),0,'category filter does not return other stories');
select extensions.lives_ok($$select public.save_magazine_category(null,0,'Synthetic category','synthetic-category',true,70)$$,'authorized category creation');
select extensions.throws_ok($$select public.save_magazine_category(null,0,'Duplicate','synthetic-category',true,70)$$,'PT409',null,'category slug collision guarded');
select extensions.lives_ok($$select public.publish_magazine(pg_temp.a(2),pg_temp.v(2),false)$$,'unpublish article');
select extensions.is(public.get_published_magazine('second-synthetic-story'),null::jsonb,'unpublished article no longer public');
select extensions.is(public.get_staff_magazine(pg_temp.a(2))->>'featured','false','unpublish clears feature');
select set_config('request.jwt.claims',pg_temp.claims(1),true);
select extensions.lives_ok($$select public.list_staff_magazine()$$,'Owner retains editorial rights');
reset role;
select extensions.throws_ok($$update business_private.magazine_revisions set snapshot='{}' where article_id=pg_temp.a(1)$$,'42501',null,'published snapshots cannot be overwritten');
select extensions.is((select count(*) from business_private.magazine_revisions where article_id=pg_temp.a(1)),2::bigint,'old revision still retained');
select extensions.ok((select count(*) from public.audit_logs where resource_id=pg_temp.a(1)::text and action='magazine.publication_changed')=2,'publications audited atomically');
create function pg_temp.reject_editorial_audit() returns trigger language plpgsql as $$begin if new.action like 'magazine.%' then raise exception 'Synthetic audit failure';end if;return new;end;$$;
create trigger reject_editorial_audit before insert on public.audit_logs for each row execute function pg_temp.reject_editorial_audit();
set local role authenticated;select set_config('request.jwt.claims',pg_temp.claims(2),true);
select extensions.throws_ok($$select public.save_magazine_draft(null,0,'audit-rollback-story',pg_temp.doc())$$,'P0001',null,'audit failure blocks draft write');
reset role;
select extensions.is((select count(*) from business_private.magazine_articles where slug='audit-rollback-story'),0::bigint,'failed audited operation rolled back completely');
select * from extensions.finish();rollback;
